"""Pure validation helpers for MarketPulse Telegram Stars subscriptions."""
from __future__ import annotations

import re
from datetime import datetime, timedelta, timezone

PRO_INVOICE_PAYLOAD = re.compile(r"^marketpulse_pro_month_(?P<telegram_id>[1-9][0-9]*)_(?P<nonce>[0-9a-f]{32})$")
PRO_SUBSCRIPTION_DAYS = 30
PRO_SUBSCRIPTION_SECONDS = 30 * 24 * 60 * 60


def valid_pro_invoice(payload: str, telegram_id: int | str, currency: str, amount: int, expected_amount: int) -> bool:
    """Accept only the exact payload format generated by the backend for this buyer."""
    match = PRO_INVOICE_PAYLOAD.fullmatch(payload or "")
    return bool(
        match
        and match.group("telegram_id") == str(telegram_id)
        and currency == "XTR"
        and amount == expected_amount
        and expected_amount > 0
    )


def subscription_end(now: datetime, previous_end: datetime | None, previous_plan: str, telegram_expiration: int | None = None) -> tuple[datetime, datetime]:
    """Return start/end dates, respecting Telegram's authoritative recurring expiry when supplied."""
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    else:
        now = now.astimezone(timezone.utc)
    if telegram_expiration:
        end = datetime.fromtimestamp(telegram_expiration, timezone.utc)
        start = now
        return start, end
    normalized_previous = previous_end
    if normalized_previous is not None:
        normalized_previous = normalized_previous.replace(tzinfo=timezone.utc) if normalized_previous.tzinfo is None else normalized_previous.astimezone(timezone.utc)
    start = normalized_previous if previous_plan == "pro" and normalized_previous and normalized_previous > now else now
    return start, start + timedelta(days=PRO_SUBSCRIPTION_DAYS)
